        tables = ",".join('"' + table.name + '"' for table in Base.metadata.sorted_tables)
        conn.execute(text(f"TRUNCATE {tables} RESTART IDENTITY CASCADE"))
    s3.cache_clear()
    with mock_aws():
        ensure_bucket()
        yield
    s3.cache_clear()


