import { useEffect, useRef, useState, type FormEvent } from "react";
import { Link, useSearchParams } from "react-router-dom";
import {
  Check,
  CloudUpload,
  FileVideo,
  Globe2,
  LockKeyhole,
  ArrowRight,
} from "lucide-react";
import { api, send, uploadFile } from "../api";
import { useAuth } from "../state";
import { ErrorBox, LoginRequired, Spinner } from "../components/UI";
import { categories, type Video } from "../types";

export default function Upload() {
  const { user, loading } = useAuth(),
    [params] = useSearchParams();
  const [file, setFile] = useState<File | null>(null),
    [title, setTitle] = useState(""),
    [description, setDescription] = useState(""),
    [category, setCategory] = useState("Другое"),
    [visibility, setVisibility] = useState("public"),
    [progress, setProgress] = useState(0),
    [busy, setBusy] = useState(false),
    [complete, setComplete] = useState(false),
    [error, setError] = useState(""),
    [id, setId] = useState(params.get("retry") || ""),
    [drag, setDrag] = useState(false);
  const controller = useRef<AbortController | null>(null),
    input = useRef<HTMLInputElement>(null);
  useEffect(() => () => controller.current?.abort(), []);
  useEffect(() => {
    if (!params.get("retry")) return;
    let active = true;
    api<Video>(`/videos/${params.get("retry")}`)
      .then((v) => {
        if (active) {
          setTitle(v.title);
          setDescription(v.description);
          setCategory(v.category);
          setVisibility(v.visibility);
        }
      })
      .catch((e) => {
        if (active) setError(e.message);
      });
    return () => {
      active = false;
    };
  }, [params]);
  useEffect(() => {
    if (!busy) return;
    const warn = (e: BeforeUnloadEvent) => e.preventDefault();
    window.addEventListener("beforeunload", warn);
    return () => window.removeEventListener("beforeunload", warn);
  }, [busy]);
  function pick(f: File | undefined) {
    if (!f) return;
    if (f.size > 536870912) {
      setError("Максимальный размер файла — 512 МБ.");
      return;
    }
    if (f.size < 32) {
      setError("Файл пустой или повреждён.");
      return;
    }
    setError("");
    setFile(f);
    if (!title) setTitle(f.name.replace(/\.[^.]+$/, ""));
  }
  async function submit(e: FormEvent) {
    e.preventDefault();
    if (!file || busy) return;
    setBusy(true);
    setError("");
    setProgress(0);
    controller.current = new AbortController();
    try {
      let videoId = id;
      const metadata = { title, description, category, visibility };
      if (!videoId) {
        const v = await send<Video>("/videos", "POST", metadata);
        videoId = v.id;
        setId(v.id);
      } else {
        await send(`/videos/${videoId}`, "PATCH", metadata);
      }
      await uploadFile(videoId, file, setProgress, controller.current.signal);
      setComplete(true);
    } catch (e) {
      setError((e as Error).message);
    } finally {
      setBusy(false);
    }
  }
  if (loading) return <Spinner />;
  if (!user) return <LoginRequired />;
  if (complete)
    return (
      <div className="upload-success">
        <span className="success-circle">
          <Check size={38} />
        </span>
        <p className="eyebrow">ФАЙЛ УЖЕ У НАС</p>
        <h1>Готовим ваше видео к просмотру</h1>
        <p>
          Загрузка завершена. Обработка продолжится в фоне —<br />
          эту страницу уже можно закрыть.
        </p>
        <div className="upload-summary">
          <FileVideo size={26} />
          <div>
            <strong>{title}</strong>
            <small>
              {visibility === "private" ? "Приватное видео" : "Открытое видео"}{" "}
              · {((file?.size || 0) / 1048576).toFixed(1)} МБ
            </small>
          </div>
        </div>
        <Link className="button primary" to="/studio">
          Перейти в студию
          <ArrowRight size={18} />
        </Link>
      </div>
    );
  return (
    <section className="upload-page">
      <div className="page-heading">
        <div>
          <p className="eyebrow">ТВОРЧЕСКАЯ СТУДИЯ</p>
          <h1>
            {params.get("retry")
              ? "Повторная загрузка"
              : "Поделитесь своей историей"}
          </h1>
          <p>Ваше следующее видео начинается здесь.</p>
        </div>
        <Link className="button secondary" to="/studio">
          Мои видео
        </Link>
      </div>
      <div className="upload-layout">
        <form className="upload-form panel" onSubmit={submit}>
          <fieldset disabled={busy}>
            <div
              className={`dropzone ${drag ? "drag" : ""} ${file ? "has-file" : ""}`}
              onDragOver={(e) => {
                e.preventDefault();
                setDrag(true);
              }}
              onDragLeave={() => setDrag(false)}
              onDrop={(e) => {
                e.preventDefault();
                setDrag(false);
                if (!busy) pick(e.dataTransfer.files[0]);
              }}
            >
              <div className="upload-icon">
                {file ? <FileVideo size={30} /> : <CloudUpload size={34} />}
              </div>
              <h2>{file ? file.name : "Перетащите видео сюда"}</h2>
              <p>
                {file
                  ? `${(file.size / 1048576).toFixed(1)} МБ · Готово к загрузке`
                  : "или выберите файл на компьютере"}
              </p>
              <button
                type="button"
                className="button secondary"
                onClick={() => input.current?.click()}
              >
                {file ? "Выбрать другой файл" : "Выбрать файл"}
              </button>
              <input
                ref={input}
                type="file"
                accept="video/mp4,video/webm,video/quicktime,video/x-msvideo,video/ogg,video/mp2t,.mkv"
                className="sr-only"
                aria-label="Видеофайл"
                onChange={(e) => pick(e.target.files?.[0])}
              />
              <small>MP4, MOV, WebM, MKV · до 512 МБ · до 2 часов</small>
            </div>
            <label>
              Название <span className="required">*</span>
              <input
                required
                maxLength={150}
                value={title}
                onChange={(e) => setTitle(e.target.value)}
                placeholder="О чём ваше видео?"
              />
              <small>{title.length}/150</small>
            </label>
            <label>
              Описание
              <textarea
                maxLength={5000}
