#!/usr/bin/env python3
"""Package tracked source, full Git history and original project-native sessions."""

import argparse
import hashlib
import json
import subprocess
import zipfile
from datetime import UTC, datetime
from pathlib import Path


def git(root, *args):
    return subprocess.check_output(["git", "-C", str(root), *args])


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--session", type=Path, action="append", required=True)
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument(
        "--allow-session-id",
        action="append",
        default=[],
        help="Explicitly approve an additional project session UUID",
    )
    args = parser.parse_args()
    root = Path(__file__).resolve().parents[1]
    if git(root, "status", "--porcelain").strip():
        raise SystemExit(
            "Commit project changes before packaging (history must match delivered source)."
        )
    # Read complete native files once. Never redact, synthesize or rewrite messages.
    sessions = []
    for path in args.session:
        data = path.read_bytes()
        records = [json.loads(line) for line in data.splitlines() if line.strip()]
        metadata = next(
            (v.get("payload", {}) for v in records if v.get("type") == "session_meta"),
            None,
        )
        if not metadata or metadata.get("id") not in {
            "01a1a14d-e714-77a0-85f2-afc12f7816ea",
            *args.allow_session_id,
        }:
            raise SystemExit("Refusing a session unrelated to this project")
        if any(sid == metadata["id"] or name == path.name for name, _, sid in sessions):
            raise SystemExit("Duplicate session ID or filename")
        sessions.append((path.name, data, metadata["id"]))
    manifest = {
        "captured_at_utc": datetime.now(UTC).isoformat(),
        "git_head": git(root, "rev-parse", "HEAD").decode().strip(),
        "format": "Original Codex JSONL, exact bytes at capture time",
        "note": "The active session may continue after this snapshot; re-run packaging for a later capture.",
        "sessions": [
            {
                "file": name,
                "session_id": sid,
                "bytes": len(data),
                "sha256": hashlib.sha256(data).hexdigest(),
            }
            for name, data, sid in sessions
        ],
    }
    args.output.parent.mkdir(parents=True, exist_ok=True)
    with zipfile.ZipFile(args.output, "w", zipfile.ZIP_DEFLATED) as archive:
        files = [
            root / p.decode() for p in git(root, "ls-files", "-z").split(b"\0") if p
        ]
        files += [p for p in (root / ".git").rglob("*") if p.is_file()]
        for path in files:
            if path.is_symlink():
                raise SystemExit(f"Refusing symlink in submission: {path.name}")
            archive.write(path, "viewtube/" + path.relative_to(root).as_posix())
        for name, data, _ in sessions:
            archive.writestr("viewtube/ai/sessions/" + name, data)
        archive.writestr(
            "viewtube/ai/sessions/manifest.json",
            json.dumps(manifest, ensure_ascii=False, indent=2),
        )
    with zipfile.ZipFile(args.output) as archive:
        if archive.testzip():
            raise SystemExit("ZIP verification failed")
    digest = hashlib.sha256(args.output.read_bytes()).hexdigest()
    args.output.with_suffix(".zip.sha256").write_text(f"{digest}  {args.output.name}\n")
    print(
        f"Created {args.output.name}: {args.output.stat().st_size} bytes, HEAD {manifest['git_head'][:8]}"
    )


if __name__ == "__main__":
    main()
import { useEffect, useState } from "react";
import { Link, useSearchParams } from "react-router-dom";
import {
  ArrowUpRight,
  ChevronLeft,
  ChevronRight,
  SlidersHorizontal,
} from "lucide-react";
import { useAuth, useQuery } from "../state";
import {
  Empty,
  ErrorBox,
  LoginRequired,
  Spinner,
  VideoGrid,
} from "../components/UI";
import { categories, type Page, type Video } from "../types";

const titles: Record<string, [string, string]> = {
  public: [
    "Найдите то, что интересно",
    "Новые видео и авторы, которых стоит открыть",
  ],
  popular: ["В тренде", "Видео, к которым возвращаются"],
  subscriptions: ["Подписки", "Новое от любимых авторов"],
  history: ["История просмотра", "Вернитесь к тому, что вас заинтересовало"],
  liked: ["Понравившиеся", "Всё, что вы отметили лайком"],
  shared: ["Доступные мне", "Приватные видео, которыми с вами поделились"],
};
export default function Feed({ scope = "public" }: { scope?: string }) {
  const { user, loading: authLoading } = useAuth(),
    [params, setParams] = useSearchParams();
  const category = categories.includes(params.get("category") || "")
    ? params.get("category")!
    : "Все";
  const [page, setPage] = useState(1),
    [sort, setSort] = useState(scope === "popular" ? "popular" : "new");
  const isSearch = location.pathname === "/search",
    q = params.get("q") || "";
  useEffect(() => {
    setPage(1);
  }, [q, category, scope]);
  const needsAuth = !["public", "popular"].includes(scope);
  const path =
    needsAuth && !user
      ? null
      : `/videos?scope=${scope === "popular" ? "public" : scope}&page=${page}&sort=${sort}&q=${encodeURIComponent(q)}&category=${encodeURIComponent(category === "Все" ? "" : category)}`;
  const { data, error, loading, reload } = useQuery<Page<Video>>(path);
  if (authLoading && needsAuth) return <Spinner />;
  if (needsAuth && !user) return <LoginRequired />;
  const title = titles[scope] || titles.public;
  return (
    <section className="feed">
      <div className="chips" aria-label="Категории видео">
        {categories.map((c) => (
          <button
            key={c}
            className={`chip ${category === c ? "selected" : ""}`}
            aria-pressed={category === c}
            onClick={() => {
              setParams((previous) => {
                const next = new URLSearchParams(previous);
                if (c === "Все") next.delete("category");
                else next.set("category", c);
                return next;
              });
              setPage(1);
            }}
          >
            {c}
          </button>
        ))}
      </div>
      <div className={`feed-heading ${scope === "public" && !isSearch ? "feed-heading-home" : ""}`}>
        {(scope !== "public" || isSearch) && <div>
          <p className="eyebrow">
            {isSearch
              ? "ПОИСК ВИДЕО"
              : scope === "public"
                ? "ВАША ПОРЦИЯ ВДОХНОВЕНИЯ"
                : "ВАША ВИДЕОТЕКА"}
          </p>
          <h1>
            {isSearch
              ? q
                ? `Результаты по запросу «${q}»`
                : "Что хотите посмотреть?"
              : title[0]}
          </h1>
          <p>
            {isSearch
              ? data
                ? `Найдено видео: ${data.total}`
                : "Ищем видео по названию"
              : title[1]}
          </p>
        </div>}
        <label className="sort">
          <SlidersHorizontal size={17} />
          <span className="sr-only">Сортировать</span>
          <select
            aria-label="Сортировка"
            value={sort}
            onChange={(e) => {
              setSort(e.target.value);
              setPage(1);
            }}
          >
            <option value="new">Сначала новые</option>
            <option value="popular">По популярности</option>
          </select>
        </label>
      </div>
      {loading ? (
        <div
          className="video-grid skeleton-grid"
          aria-label="Загрузка видео"
          role="status"
        >
          {Array.from({ length: 9 }, (_, i) => (
            <div key={i} className="skeleton-card">
              <div />
              <span />
              <span />
            </div>
          ))}
        </div>
      ) : error ? (
        <ErrorBox message={error} retry={reload} />
      ) : data?.items.length ? (
        <>
          <VideoGrid videos={data.items} />
          {data.total > data.limit && (
            <div className="pagination">
              <button
                className="button secondary"
                disabled={page === 1}
                onClick={() => {
                  setPage((p) => p - 1);
                  window.scrollTo(0, 0);
                }}
              >
                <ChevronLeft size={18} />
                Назад
              </button>
              <span>
                {page} / {Math.ceil(data.total / data.limit)}
              </span>
              <button
                className="button secondary"
                disabled={page * data.limit >= data.total}
                onClick={() => {
                  setPage((p) => p + 1);
                  window.scrollTo(0, 0);
                }}
              >
                Далее
                <ChevronRight size={18} />
              </button>
            </div>
          )}
        </>
      ) : (
        <Empty
          title={isSearch ? "Ничего не нашлось" : "Здесь пока нет видео"}
          description={
            isSearch
              ? "Попробуйте другое название или выберите категорию «Все»."
              : "Начните с главной страницы или поделитесь своим первым видео."
          }
        >
          <Link
            className="button secondary"
            to={scope === "public" ? "/upload" : "/"}
          >
            {scope === "public" ? "Загрузить видео" : "Открыть главную"}
            <ArrowUpRight size={17} />
          </Link>
        </Empty>
      )}
    </section>
  );
}
